changeSet.sql:
create table data.tg_command_log(
 id      bigserial primary key,
 id_user int4 not null constraint fk_tg_command_log_user references data.users(id),
 command varchar(1000) not null,
 ts_db   timestamp DEFAULT LOCALTIMESTAMP NOT NULL
);

create index idx_tg_command_log_user on data.tg_command_log(id_user, ts_db desc);
